using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Dovetail.Build.Tasks;

/// <summary>
///     The two files built from configuration schema fragments, and how they are written.
/// </summary>
internal static class ConfigurationSchemaDocument
{
    /// <summary>
    ///     The draft both files use.
    /// </summary>
    public const string Draft = "http://json-schema.org/draft-07/schema#";

    private const string GeneratedComment =
        "Generated by Dovetail from the configuration sections this project and its references declare; the build overwrites it.";

    private const string SchemaStoreComment =
        " definitions/" + SchemaStoreAppSettings.DefinitionName + " is SchemaStore's appsettings.json schema (" + SchemaStoreAppSettings.SourceUrl
      + ", Apache License 2.0), with its $schema, $id and title removed and its local $refs rewritten to point into that definition.";

    private static readonly UTF8Encoding Utf8 = new(encoderShouldEmitUTF8Identifier: false);

    /// <summary>
    ///     An application's merged, strict schema: every section of every fragment (see <see cref="ApplicationSchemaBuilder" />),
    ///     and, when <paramref name="includeSchemaStore" /> is set, SchemaStore's appsettings schema as the base:
    ///     <c>allOf: [{"$ref": "#/definitions/SchemaStoreAppSettings"}, {Dovetail's part}]</c>.
    /// </summary>
    public static JsonObject CreateApplicationSchema(IEnumerable<ConfigurationSchemaFragment> fragments, bool strict, bool includeSchemaStore)
    {
        var builder = new ApplicationSchemaBuilder(strict, new());
        var dovetail = builder.Build(SectionNode.CreateTree(fragments));
        var definitions = new JsonObject();
        if (includeSchemaStore) definitions[SchemaStoreAppSettings.DefinitionName] = SchemaStoreAppSettings.Load();
        foreach (var definition in builder.BuildDefinitions())
        {
            definitions[definition.Key] = definition.Value;
        }

        var document = new JsonObject
        {
            ["$schema"] = Draft,
            ["$comment"] = includeSchemaStore ? GeneratedComment + SchemaStoreComment : GeneratedComment,
        };
        if (definitions.Count > 0) document["definitions"] = definitions;

        if (includeSchemaStore)
        {
            document["allOf"] = new JsonArray(new JsonObject { ["$ref"] = SchemaStoreAppSettings.Reference, }, dovetail);
        }
        else
        {
            foreach (var keyword in dovetail.ToArray())
            {
                dovetail.Remove(keyword.Key);
                document[keyword.Key] = keyword.Value;
            }
        }

        return document;
    }

    /// <summary>
    ///     A library's own sections, permissive and rooted at the configuration root the way Aspire's
    ///     <c>ConfigurationSchema.json</c> is: <c>{"type": "object", "properties": {"Section": {...}}}</c>, with the fragments'
    ///     definitions hoisted into the root <c>definitions</c>. A section declared more than once is an <c>allOf</c> of its
    ///     declarations. <see langword="null" /> when there are no fragments.
    /// </summary>
    public static JsonObject? CreateLibrarySchema(IEnumerable<ConfigurationSchemaFragment> fragments)
    {
        var root = SectionNode.CreateTree(fragments);
        if (root.Children.Count == 0) return null;

        var registry = new DefinitionRegistry();
        var document = new JsonObject { ["type"] = "object", ["properties"] = LibraryProperties([], root.Children, registry), };
        var definitions = new JsonObject();
        foreach (var definition in registry.Definitions)
        {
            definitions[definition.Name] = definition.Schema.DeepClone();
        }

        if (definitions.Count > 0) document["definitions"] = definitions;
        return document;
    }

    /// <summary>
    ///     Serializes a document the same way every time: two-space indentation, <c>\n</c> line breaks and a final one, no
    ///     escaping beyond what JSON requires, UTF-8 without a byte order mark (see <see cref="Write" />).
    /// </summary>
    public static string Serialize(JsonNode document)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new() { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping, Indented = true, NewLine = "\n", }))
        {
            document.WriteTo(writer);
        }

        return Utf8.GetString(stream.ToArray()) + "\n";
    }

    /// <summary>
    ///     Writes <paramref name="content" /> to <paramref name="path" /> unless the file already holds exactly that, so an
    ///     unchanged schema keeps its timestamp (editors and incremental copies don't see a change).
    /// </summary>
    /// <returns>Whether the file was written.</returns>
    public static bool Write(string path, string content)
    {
        var bytes = Utf8.GetBytes(content);
        if (File.Exists(path) && File.ReadAllBytes(path).AsSpan().SequenceEqual(bytes)) return false;

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllBytes(path, bytes);
        return true;
    }

    private static JsonObject LibraryProperties(IReadOnlyList<string> path, IReadOnlyList<SectionNode> sections, DefinitionRegistry registry)
    {
        var properties = new JsonObject();
        foreach (var section in sections)
        {
            IReadOnlyList<string> sectionPath = [.. path, section.Name];
            var parts = section.Fragments.Select(z => registry.Root(z, sectionPath).DeepClone()).ToList();
            if (section.Children.Count > 0) parts.Add(new JsonObject { ["type"] = "object", ["properties"] = LibraryProperties(sectionPath, section.Children, registry), });
            properties[section.Name] = parts.Count == 1 ? parts[0] : new JsonObject { ["allOf"] = new JsonArray([.. parts]), };
        }

        return properties;
    }
}
